import{_ as t,a as i,b as a}from"./chunks/details-yaml.FET-twd8.js";import{_ as s,o,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Home Assistant Automation Exporter","description":"Documentation en français concernant un outil Windows permettant d\'exporter des automatisations Home Assistant individuelles depuis le fichier `automations.yaml`.","frontmatter":{"title":"Home Assistant Automation Exporter","description":"Documentation en français concernant un outil Windows permettant d\'exporter des automatisations Home Assistant individuelles depuis le fichier `automations.yaml`."},"headers":[],"relativePath":"fr/collection/ha-automation-exporter/index.md","filePath":"fr/collection/ha-automation-exporter/index.md","lastUpdated":1793126673000}'),l={name:"fr/collection/ha-automation-exporter/index.md"};function d(u,e,c,p,m,h){return o(),n("div",null,[...e[0]||(e[0]=[r('<p><a id="orientation-actuelle"></a></p><h1 id="home-assistant-automation-exporter" tabindex="-1">Home Assistant Automation Exporter <a class="header-anchor" href="#home-assistant-automation-exporter" aria-label="Permalink to &quot;Home Assistant Automation Exporter {#home-assistant-automation-exporter}&quot;">​</a></h1><p><strong>Home Assistant Automation Exporter</strong> est un outil portable pour Windows qui permet de charger un fichier Home Assistant <code>automations.yaml</code> et d&#39;en exporter le contenu sous forme de fichiers YAML individuels.</p><p>Cela s&#39;avère utile si vous souhaitez sauvegarder des automatisations séparément, les partager, les documenter ou les réimporter individuellement dans Home Assistant ultérieurement.</p><p><img src="'+t+'" alt="Home Assistant Automation Exporter"></p><h2 id="projekt" tabindex="-1">Projet <a class="header-anchor" href="#projekt" aria-label="Permalink to &quot;Projet {#projekt}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Élément</th><th>Lien</th></tr></thead><tbody><tr><td>Dépôt GitHub</td><td><a href="https://github.com/rockbaer2007/ha-automation-exporter" target="_blank" rel="noreferrer">rockbaer2007/ha-automation-exporter</a></td></tr><tr><td>Version actuelle</td><td><a href="https://github.com/rockbaer2007/ha-automation-exporter/releases/tag/v0.3.4" target="_blank" rel="noreferrer">Télécharger la v0.3.4</a></td></tr><tr><td>Plateforme</td><td>Windows</td></tr><tr><td>Base</td><td>C# / .NET 9</td></tr></tbody></table><h2 id="funktionen" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Fonctionnalités {#funktionen}&quot;">​</a></h2><ul><li>Interface graphique Windows (sans ligne de commande).</li><li>Affichage de la version du programme dans le titre de la fenêtre.</li><li>Chargement d&#39;un fichier Home Assistant <code>automations.yaml</code>.</li><li>Recherche d&#39;automatisations par alias, ID, nom de fichier ou contenu YAML.</li><li>Affichage de toutes les automatisations dans un tableau avec cases à cocher.</li><li>Accès à des vues détaillées incluant les entités détectées et le code YAML complet.</li><li>Exportation des automatisations sélectionnées sous forme de fichiers individuels <code>.yaml</code>.</li><li>Ouverture directe du dossier d&#39;exportation dans l&#39;Explorateur Windows. - Enregistre les paramètres de manière portable, à côté du fichier EXE, dans <code>HaAutomationExporter.settings.json</code>.</li></ul><h2 id="voraussetzungen" tabindex="-1">Exigences <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Exigences {#voraussetzungen}&quot;">​</a></h2><p>Pour une utilisation en tant que version finale (release) :</p><ul><li>Windows</li><li>Téléchargement du fichier de la version actuelle depuis GitHub</li></ul><p>Pour le développement ou l&#39;exécution à partir du code source :</p><ul><li>Windows</li><li>.NET 9 SDK</li><li>Dépôt cloné localement</li></ul><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project .\\HaAutomationExporter.csproj</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="bedienung" tabindex="-1">Utilisation <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Utilisation {#bedienung}&quot;">​</a></h2><ol><li>Lancer le programme.</li><li>Sélectionner le fichier Home Assistant <code>automations.yaml</code>.</li><li>Modifier éventuellement le dossier d&#39;exportation dans les paramètres.</li><li>Sélectionner les automatisations dans le tableau.</li><li>Vérifier des automatisations individuelles via <code>Details</code>.</li><li>Exporter les automatisations sélectionnées.</li><li>Importer les fichiers YAML générés dans Home Assistant, si nécessaire.</li></ol><h2 id="detailansicht" tabindex="-1">Vue détaillée <a class="header-anchor" href="#detailansicht" aria-label="Permalink to &quot;Vue détaillée {#detailansicht}&quot;">​</a></h2><p>La vue détaillée permet de vérifier une automatisation avant son exportation. Cela s&#39;avère particulièrement utile lorsque de nombreuses automatisations portent des noms similaires, ou lorsqu&#39;il est nécessaire de contrôler des modèles (templates) et des entités.</p><p><img src="'+i+'" alt="Détails de l&#39;automatisation : Entités"></p><p>L&#39;onglet <strong>Entités</strong> affiche les entités Home Assistant détectées, en précisant leur source, le numéro de ligne et le contexte. Les éléments détectés au sein de modèles (templates) sont identifiés par une approche heuristique.</p><p><img src="'+a+`" alt="Détails de l&#39;automatisation : YAML"></p><p>L&#39;onglet <strong>YAML</strong> affiche le code complet de l&#39;automatisation et propose une fonction de copie.</p><h2 id="export-fur-home-assistant" tabindex="-1">Exportation pour Home Assistant <a class="header-anchor" href="#export-fur-home-assistant" aria-label="Permalink to &quot;Exportation pour Home Assistant {#export-fur-home-assistant}&quot;">​</a></h2><p>Les fichiers exportés sont préparés de manière à faciliter leur utilisation individuelle dans Home Assistant.</p><p>L&#39;outil d&#39;exportation supprime la ligne initiale <code>id:</code> et normalise les différentes syntaxes YAML :</p><table tabindex="0"><thead><tr><th>Source</th><th>Exportation</th></tr></thead><tbody><tr><td><code>triggers</code></td><td><code>trigger</code></td></tr><tr><td><code>conditions</code></td><td><code>condition</code></td></tr><tr><td><code>actions</code></td><td><code>action</code></td></tr><tr><td><code>- trigger: ...</code></td><td><code>- platform: ...</code></td></tr><tr><td>Actions de service</td><td><code>- service: domain.service</code></td></tr></tbody></table><p>Cela permet d&#39;exporter de manière plus uniforme les automatisations provenant de différentes versions de Home Assistant, d&#39;exemples sur GitHub ou de messages sur des forums.</p><h2 id="sprachen" tabindex="-1">Langues <a class="header-anchor" href="#sprachen" aria-label="Permalink to &quot;Langues {#sprachen}&quot;">​</a></h2><p>L&#39;interface prend en charge :</p><ul><li>Système</li><li>Allemand</li><li>Anglais</li><li>Français</li><li>Espagnol</li><li>Polonais</li><li>Russe</li></ul><p>L&#39;option <code>System</code> détecte la langue du système Windows pour <code>de</code>, <code>en</code>, <code>fr</code>, <code>es</code>, <code>pl</code> et <code>ru</code>. Si une langue système n&#39;est pas prise en charge, l&#39;application bascule sur l&#39;anglais.</p><h2 id="kommandozeile" tabindex="-1">Ligne de commande <a class="header-anchor" href="#kommandozeile" aria-label="Permalink to &quot;Ligne de commande {#kommandozeile}&quot;">​</a></h2><p>Le projet est conçu comme une application Windows, ce qui lui permet de démarrer sans fenêtre de console. En interne, il reste toutefois possible de traiter des arguments.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HaAutomationExporter.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\path\\automations.yaml C:\\path\\export</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HaAutomationExporter.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\path\\automations.yaml C:\\path\\export pool</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>L&#39;interface graphique est prévue pour une utilisation courante.</p><h2 id="hinweise" tabindex="-1">Remarques <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Remarques {#hinweise}&quot;">​</a></h2><ul><li>Avant toute importation dans Home Assistant, il est conseillé de vérifier brièvement chaque automatisation exportée.</li><li>Les automatisations contenant des modèles (templates) complexes peuvent nécessiter une vérification manuelle.</li><li>Le fichier source <code>automations.yaml</code> est uniquement lu et n&#39;est pas modifié.</li><li>Le dossier d&#39;exportation doit être situé en dehors de la configuration de production de Home Assistant, tant que les fichiers n&#39;ont pas été vérifiés.</li></ul>`,38)])])}const x=s(l,[["render",d]]);export{b as __pageData,x as default};
